-- Communications C2-B1 (docs/communications-c2.md §16): mailbox kind (PERSONAL/BUSINESS), the four
-- mailbox identities (authenticated principal, target mailbox, organisational controller, credential
-- holder), verified business domains, designated business addresses, per-mailbox members (READ/SEND),
-- and the business's explicit ordinary-communications retention period. Generated by
-- `prisma migrate diff`, then the backfill, constraints, guards, grants and RLS Prisma cannot express
-- were added by hand (sections marked "hand-written"). One transaction (docs/migration-readiness.md §7).
--
-- Ordering: depends only on 20261121000000_communications_providers (mail_connections and friends) and
-- 20261113150000_tenancy (businesses, memberships, audit_events). It references no finance, people,
-- scheduling or reporting object, so it commutes with F5/F6/R1; the name sorts after every migration on
-- main and after the open F6 (20261123000000) and R1 (20261124000000) branches.
-- Additive: new columns (existing connections become PERSONAL, holder = owner, principal = target),
-- new tables, one replaced guard function. No mail content is stored by anything in this migration.
BEGIN;
-- AlterTable (credential_holder_id and principal_account_id become NOT NULL after the backfill below)
ALTER TABLE "mail_connections" ADD COLUMN     "business_address_id" UUID,
ADD COLUMN     "credential_holder_id" UUID,
ADD COLUMN     "kind" TEXT NOT NULL DEFAULT 'PERSONAL',
ADD COLUMN     "principal_account_id" TEXT,
ADD COLUMN     "provider_tenant_id" TEXT;

-- AlterTable
ALTER TABLE "mail_oauth_states" ADD COLUMN     "business_address_id" UUID;

-- CreateTable
CREATE TABLE "mail_business_domains" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "domain" TEXT NOT NULL,
    "verification_token_hash" CHAR(64) NOT NULL,
    "verified_at" TIMESTAMPTZ,
    "verified_by_id" UUID,
    "created_by_id" UUID NOT NULL,
    "removed_at" TIMESTAMPTZ,
    "removed_by_id" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_business_domains_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "mail_business_addresses" (
    "id" UUID NOT NULL,
    "business_id" UUID NOT NULL,
    "address" TEXT NOT NULL,
    "domain_id" UUID,
    "attested_by_id" UUID,
    "attested_at" TIMESTAMPTZ,
    "attestation_version" TEXT,
    "created_by_id" UUID NOT NULL,
    "removed_at" TIMESTAMPTZ,
    "removed_by_id" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_business_addresses_pkey" PRIMARY KEY ("business_id","id")
);

-- CreateTable
CREATE TABLE "mail_connection_members" (
    "business_id" UUID NOT NULL,
    "connection_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "access" TEXT NOT NULL,
    "granted_by_id" UUID NOT NULL,
    "granted_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "version" INTEGER NOT NULL DEFAULT 1,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_connection_members_pkey" PRIMARY KEY ("business_id","connection_id","user_id")
);

-- CreateTable
CREATE TABLE "mail_retention_settings" (
    "business_id" UUID NOT NULL,
    "ordinary_retention_days" INTEGER NOT NULL,
    "updated_by_id" UUID NOT NULL,
    "version" INTEGER NOT NULL DEFAULT 1,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "mail_retention_settings_pkey" PRIMARY KEY ("business_id")
);

-- CreateIndex
CREATE INDEX "mail_business_addresses_business_id_domain_id_idx" ON "mail_business_addresses"("business_id", "domain_id");

-- CreateIndex
CREATE INDEX "mail_connection_members_business_id_user_id_idx" ON "mail_connection_members"("business_id", "user_id");

-- CreateIndex
CREATE INDEX "mail_connections_business_id_credential_holder_id_idx" ON "mail_connections"("business_id", "credential_holder_id");

-- CreateIndex
CREATE INDEX "mail_connections_business_id_business_address_id_idx" ON "mail_connections"("business_id", "business_address_id");

-- AddForeignKey
ALTER TABLE "mail_connections" ADD CONSTRAINT "mail_connections_business_address_fkey" FOREIGN KEY ("business_id", "business_address_id") REFERENCES "mail_business_addresses"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_oauth_states" ADD CONSTRAINT "mail_oauth_states_business_address_fkey" FOREIGN KEY ("business_id", "business_address_id") REFERENCES "mail_business_addresses"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_business_domains" ADD CONSTRAINT "mail_business_domains_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_business_addresses" ADD CONSTRAINT "mail_business_addresses_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_business_addresses" ADD CONSTRAINT "mail_business_addresses_domain_fkey" FOREIGN KEY ("business_id", "domain_id") REFERENCES "mail_business_domains"("business_id", "id") ON DELETE NO ACTION ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_connection_members" ADD CONSTRAINT "mail_connection_members_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "mail_connection_members" ADD CONSTRAINT "mail_connection_members_connection_fkey" FOREIGN KEY ("business_id", "connection_id") REFERENCES "mail_connections"("business_id", "id") ON DELETE CASCADE ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_connection_members" ADD CONSTRAINT "mail_connection_members_membership_fkey" FOREIGN KEY ("business_id", "user_id") REFERENCES "memberships"("business_id", "user_id") ON DELETE CASCADE ON UPDATE NO ACTION;

-- AddForeignKey
ALTER TABLE "mail_retention_settings" ADD CONSTRAINT "mail_retention_settings_business_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE ON UPDATE CASCADE;



-- =============================================================================================
-- Hand-written: backfill, constraints, guards, grants and RLS.
-- SQLSTATE class CM, continued: CM008 credential holder change refused, CM009 ordinary-communications
-- retention period not set, CM010 business mailbox rule (designation, classification, membership).
-- =============================================================================================

-- ---- backfill existing connections (C2-A rows are all personal) --------------------------------
-- The table forces RLS and has no policy for the owner role (so the owner would see no row), and the C2-A guard refuses any update of
-- a DISCONNECTED row. Both are lifted for this one statement, inside this transaction, as the table
-- owner; nothing else runs in between. Production had no connection rows when this was written.
ALTER TABLE "mail_connections" NO FORCE ROW LEVEL SECURITY;
ALTER TABLE "mail_connections" DISABLE TRIGGER mail_connections_guard_update;
UPDATE "mail_connections" SET "credential_holder_id" = "owner_user_id", "principal_account_id" = "provider_account_id";
ALTER TABLE "mail_connections" ENABLE TRIGGER mail_connections_guard_update;
ALTER TABLE "mail_connections" FORCE ROW LEVEL SECURITY;
ALTER TABLE "mail_connections" ALTER COLUMN "credential_holder_id" SET NOT NULL, ALTER COLUMN "principal_account_id" SET NOT NULL;

-- ---- consumer mail domains -----------------------------------------------------------------------
-- Addresses on these domains cannot pass DNS domain verification; they may be designated as business
-- mailboxes only with an OWNER attestation (owner decision D-C2-3). Mirrored by CONSUMER_MAIL_DOMAINS in
-- modules/communications/server/business-mailboxes.ts (an integration test compares the two).
CREATE FUNCTION mail_is_consumer_domain(p_domain text) RETURNS boolean
LANGUAGE sql IMMUTABLE PARALLEL SAFE SET search_path = pg_catalog AS $$
  SELECT p_domain = ANY (ARRAY['gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'msn.com',
                             'hotmail.co.uk', 'live.co.uk', 'outlook.com.au', 'hotmail.com.au', 'live.com.au'])
$$;

-- Serialises every check of "is this address a business mailbox / a personal connection" for one
-- address in one business, so a designation and a personal connection of the same address can never
-- both commit (each side checks the other under the same transaction-scoped lock).
CREATE FUNCTION mail_lock_address(p_business uuid, p_address text) RETURNS void
LANGUAGE sql VOLATILE SET search_path = pg_catalog AS $$
  SELECT pg_advisory_xact_lock(hashtextextended('bos:mail-address:' || p_business::text || ':' || p_address, 0))
$$;

-- ---- mail_connections ------------------------------------------------------------------------
ALTER TABLE "mail_connections" DROP CONSTRAINT mail_connections_sharing_values;
ALTER TABLE "mail_connections"
  ADD CONSTRAINT mail_connections_kind_values CHECK ("kind" IN ('PERSONAL', 'BUSINESS')),
  -- PERSONAL keeps the owner's C2-A switch; a BUSINESS mailbox is shared through its member list only.
  ADD CONSTRAINT mail_connections_sharing_values CHECK (
    ("kind" = 'PERSONAL' AND "sharing" IN ('OWNER_ONLY', 'BUSINESS')) OR ("kind" = 'BUSINESS' AND "sharing" = 'MEMBERS')),
  ADD CONSTRAINT mail_connections_business_address_pair CHECK (("kind" = 'BUSINESS') = ("business_address_id" IS NOT NULL)),
  -- A personal mailbox's grant is always its owner's, for the owner's own account.
  ADD CONSTRAINT mail_connections_personal_holder CHECK ("kind" = 'BUSINESS' OR "credential_holder_id" = "owner_user_id"),
  ADD CONSTRAINT mail_connections_personal_principal CHECK ("kind" = 'BUSINESS' OR "principal_account_id" = "provider_account_id"),
  ADD CONSTRAINT mail_connections_principal_length CHECK (char_length("principal_account_id") BETWEEN 1 AND 255),
  ADD CONSTRAINT mail_connections_tenant_format CHECK (
    "provider_tenant_id" IS NULL OR ("provider" = 'MICROSOFT' AND "provider_tenant_id" ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')),
  ADD CONSTRAINT mail_connections_business_tenant CHECK ("kind" = 'PERSONAL' OR "provider" = 'GOOGLE' OR "provider_tenant_id" IS NOT NULL);

-- Is this address designated as a business mailbox (live designation) in this business?
-- Parameters are p_-prefixed: in a SQL function an unqualified name resolves to a column first.
CREATE FUNCTION mail_address_is_designated(p_business uuid, p_address text) RETURNS boolean
LANGUAGE sql STABLE SECURITY INVOKER SET search_path = pg_catalog, public AS $$
  SELECT EXISTS (SELECT 1 FROM "mail_business_addresses" a
                 WHERE a."business_id" = p_business AND a."address" = p_address AND a."removed_at" IS NULL)
$$;

CREATE FUNCTION mail_connections_guard_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  addr record;
BEGIN
  IF NEW.credential_holder_id IS DISTINCT FROM NEW.owner_user_id THEN
    RAISE EXCEPTION 'a new connection holds its creator''s grant' USING ERRCODE = 'CM008';
  END IF;
  PERFORM mail_lock_address(NEW.business_id, NEW.mailbox_address);
  IF NEW.kind = 'PERSONAL' THEN
    -- T-C2-2: a designated business address is never connected as someone's personal mailbox.
    IF mail_address_is_designated(NEW.business_id, NEW.mailbox_address) THEN
      RAISE EXCEPTION 'address is a business mailbox' USING ERRCODE = 'CM010';
    END IF;
  ELSE
    SELECT a."address", a."domain_id", a."attested_at", d."verified_at", d."removed_at" AS domain_removed_at, a."removed_at"
      INTO addr
      FROM "mail_business_addresses" a
      LEFT JOIN "mail_business_domains" d ON d."business_id" = a."business_id" AND d."id" = a."domain_id"
     WHERE a."business_id" = NEW.business_id AND a."id" = NEW.business_address_id;
    IF NOT FOUND OR addr.removed_at IS NOT NULL OR addr.address IS DISTINCT FROM NEW.mailbox_address
       OR NOT ((addr.domain_id IS NOT NULL AND addr.verified_at IS NOT NULL AND addr.domain_removed_at IS NULL) OR addr.attested_at IS NOT NULL) THEN
      RAISE EXCEPTION 'business mailbox needs a live designation of this address' USING ERRCODE = 'CM010';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_connections_guard_insert BEFORE INSERT ON "mail_connections" FOR EACH ROW EXECUTE FUNCTION mail_connections_guard_insert();

-- Replaces the C2-A guard (same CM005/CM006 rules) and adds the C2-B1 rules.
CREATE OR REPLACE FUNCTION mail_connections_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.provider, NEW.provider_account_id, NEW.owner_user_id, NEW.created_at, NEW.kind, NEW.business_address_id)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.provider, OLD.provider_account_id, OLD.owner_user_id, OLD.created_at, OLD.kind, OLD.business_address_id) THEN
    RAISE EXCEPTION 'connection identity is fixed' USING ERRCODE = 'CM005';
  END IF;
  IF OLD.status = 'DISCONNECTED' THEN
    RAISE EXCEPTION 'disconnected connections are final' USING ERRCODE = 'CM006';
  END IF;
  -- The tenant can be learned once (a C2-A Microsoft row has none), never changed.
  IF OLD.provider_tenant_id IS NOT NULL AND NEW.provider_tenant_id IS DISTINCT FROM OLD.provider_tenant_id THEN
    RAISE EXCEPTION 'connection tenant is fixed' USING ERRCODE = 'CM005';
  END IF;
  -- A business mailbox is its designated address.
  IF OLD.kind = 'BUSINESS' AND NEW.mailbox_address IS DISTINCT FROM OLD.mailbox_address THEN
    RAISE EXCEPTION 'business mailbox address is fixed' USING ERRCODE = 'CM005';
  END IF;
  IF OLD.kind = 'PERSONAL' AND NEW.mailbox_address IS DISTINCT FROM OLD.mailbox_address THEN
    PERFORM mail_lock_address(NEW.business_id, NEW.mailbox_address);
    IF mail_address_is_designated(NEW.business_id, NEW.mailbox_address) THEN
      RAISE EXCEPTION 'address is a business mailbox' USING ERRCODE = 'CM010';
    END IF;
  END IF;
  -- T-C2-1: the holder (and the principal it signs in as) changes only when a BUSINESS mailbox that
  -- needs reauthorisation is reconnected, and only to the member doing it. Leaving ACTIVE deleted the
  -- previous holder's tokens (mail_connections_drop_credentials), so no code path can keep them
  -- alongside a new holder. A handover is: ACTIVE -> NEEDS_REAUTH, then this transition.
  IF (NEW.credential_holder_id, NEW.principal_account_id) IS DISTINCT FROM (OLD.credential_holder_id, OLD.principal_account_id) THEN
    IF OLD.kind <> 'BUSINESS' OR OLD.status <> 'NEEDS_REAUTH' OR NEW.status <> 'ACTIVE'
       OR NEW.credential_holder_id IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid THEN
      RAISE EXCEPTION 'credential holder changes only by a business mailbox reconnect' USING ERRCODE = 'CM008';
    END IF;
  END IF;
  -- Owner clarification (2026-11-15): personal mailbox content is shared with the business only once
  -- the business has an explicit ordinary-communications retention period.
  IF NEW.sharing = 'BUSINESS' AND OLD.sharing IS DISTINCT FROM 'BUSINESS'
     AND NOT EXISTS (SELECT 1 FROM "mail_retention_settings" r WHERE r."business_id" = NEW.business_id) THEN
    RAISE EXCEPTION 'set an ordinary-communications retention period first' USING ERRCODE = 'CM009';
  END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.status_changed_at := now();
  END IF;
  RETURN NEW;
END $$;

-- ---- mail_oauth_states -----------------------------------------------------------------------
ALTER TABLE "mail_oauth_states"
  ADD CONSTRAINT mail_oauth_states_one_target CHECK ("connection_id" IS NULL OR "business_address_id" IS NULL);

-- ---- mail_sync_jobs: no sync of a BUSINESS mailbox before the retention period is set ------------
CREATE FUNCTION mail_sync_jobs_guard_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "mail_connections" c WHERE c."business_id" = NEW.business_id AND c."id" = NEW.connection_id AND c."kind" = 'BUSINESS')
     AND NOT EXISTS (SELECT 1 FROM "mail_retention_settings" r WHERE r."business_id" = NEW.business_id) THEN
    RAISE EXCEPTION 'set an ordinary-communications retention period first' USING ERRCODE = 'CM009';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_sync_jobs_guard_insert BEFORE INSERT ON "mail_sync_jobs" FOR EACH ROW EXECUTE FUNCTION mail_sync_jobs_guard_insert();

-- ---- mail_business_domains -------------------------------------------------------------------
ALTER TABLE "mail_business_domains"
  ADD CONSTRAINT mail_business_domains_format CHECK (
    char_length("domain") BETWEEN 4 AND 253 AND "domain" = lower("domain")
    AND "domain" ~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,61}[a-z0-9]$'),
  ADD CONSTRAINT mail_business_domains_not_consumer CHECK (NOT mail_is_consumer_domain("domain")),
  ADD CONSTRAINT mail_business_domains_hash_format CHECK ("verification_token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT mail_business_domains_verified_pair CHECK (("verified_at" IS NULL) = ("verified_by_id" IS NULL)),
  ADD CONSTRAINT mail_business_domains_removed_pair CHECK (("removed_at" IS NULL) = ("removed_by_id" IS NULL)),
  ADD CONSTRAINT mail_business_domains_version_positive CHECK ("version" >= 1);
CREATE UNIQUE INDEX "mail_business_domains_live_key" ON "mail_business_domains" ("business_id", "domain") WHERE "removed_at" IS NULL;

CREATE FUNCTION mail_business_domains_stamp_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  -- A domain is always added unverified; verification is a later, audited step.
  NEW.created_at := now();
  NEW.verified_at := NULL;
  NEW.verified_by_id := NULL;
  NEW.removed_at := NULL;
  NEW.removed_by_id := NULL;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_business_domains_stamp_insert BEFORE INSERT ON "mail_business_domains" FOR EACH ROW EXECUTE FUNCTION mail_business_domains_stamp_insert();

CREATE FUNCTION mail_business_domains_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.domain, NEW.verification_token_hash, NEW.created_by_id, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.domain, OLD.verification_token_hash, OLD.created_by_id, OLD.created_at) THEN
    RAISE EXCEPTION 'domain identity is fixed' USING ERRCODE = 'CM005';
  END IF;
  IF OLD.removed_at IS NOT NULL THEN
    RAISE EXCEPTION 'removed domains are final' USING ERRCODE = 'CM006';
  END IF;
  IF OLD.verified_at IS NOT NULL AND (NEW.verified_at, NEW.verified_by_id) IS DISTINCT FROM (OLD.verified_at, OLD.verified_by_id) THEN
    RAISE EXCEPTION 'verification is recorded once' USING ERRCODE = 'CM005';
  END IF;
  IF NEW.removed_at IS NOT NULL AND EXISTS (
       SELECT 1 FROM "mail_business_addresses" a WHERE a."business_id" = NEW.business_id AND a."domain_id" = NEW.id AND a."removed_at" IS NULL) THEN
    RAISE EXCEPTION 'domain has designated addresses' USING ERRCODE = 'CM010';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_business_domains_guard_update BEFORE UPDATE ON "mail_business_domains" FOR EACH ROW EXECUTE FUNCTION mail_business_domains_guard_update();

-- ---- mail_business_addresses -----------------------------------------------------------------
ALTER TABLE "mail_business_addresses"
  ADD CONSTRAINT mail_business_addresses_format CHECK (
    char_length("address") BETWEEN 3 AND 320 AND "address" = lower("address") AND position('@' in "address") > 1),
  -- Exactly one basis: a verified domain, or an OWNER attestation (consumer domains only).
  ADD CONSTRAINT mail_business_addresses_one_basis CHECK (("domain_id" IS NULL) <> ("attested_by_id" IS NULL)),
  ADD CONSTRAINT mail_business_addresses_attestation_triple CHECK (
    ("attested_by_id" IS NULL) = ("attested_at" IS NULL) AND ("attested_by_id" IS NULL) = ("attestation_version" IS NULL)),
  ADD CONSTRAINT mail_business_addresses_attestation_version CHECK ("attestation_version" IS NULL OR "attestation_version" ~ '^v[0-9]{1,3}$'),
  ADD CONSTRAINT mail_business_addresses_removed_pair CHECK (("removed_at" IS NULL) = ("removed_by_id" IS NULL)),
  ADD CONSTRAINT mail_business_addresses_version_positive CHECK ("version" >= 1);
CREATE UNIQUE INDEX "mail_business_addresses_live_key" ON "mail_business_addresses" ("business_id", "address") WHERE "removed_at" IS NULL;

CREATE FUNCTION mail_business_addresses_guard_insert() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
DECLARE
  host text := split_part(NEW.address, '@', 2);
BEGIN
  NEW.created_at := now();
  NEW.removed_at := NULL;
  NEW.removed_by_id := NULL;
  IF NEW.domain_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM "mail_business_domains" d
                   WHERE d."business_id" = NEW.business_id AND d."id" = NEW.domain_id AND d."domain" = host
                     AND d."verified_at" IS NOT NULL AND d."removed_at" IS NULL) THEN
      RAISE EXCEPTION 'address must be on a verified domain of this business' USING ERRCODE = 'CM010';
    END IF;
  ELSE
    -- Attestation: consumer domains only, by the session user, at database time.
    IF NOT mail_is_consumer_domain(host) THEN
      RAISE EXCEPTION 'custom domains need DNS verification' USING ERRCODE = 'CM010';
    END IF;
    IF NEW.attested_by_id IS DISTINCT FROM nullif(current_setting('app.user_id', true), '')::uuid THEN
      RAISE EXCEPTION 'attestation is by the session user' USING ERRCODE = 'CM010';
    END IF;
    NEW.attested_at := now();
  END IF;
  -- T-C2-2: never designate an address someone has connected as their personal mailbox here; that
  -- connection must be disconnected first (its unshared content is never carried over).
  PERFORM mail_lock_address(NEW.business_id, NEW.address);
  IF EXISTS (SELECT 1 FROM "mail_connections" c
             WHERE c."business_id" = NEW.business_id AND c."mailbox_address" = NEW.address AND c."kind" = 'PERSONAL' AND c."status" <> 'DISCONNECTED') THEN
    RAISE EXCEPTION 'address is connected as a personal mailbox' USING ERRCODE = 'CM010';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_business_addresses_guard_insert BEFORE INSERT ON "mail_business_addresses" FOR EACH ROW EXECUTE FUNCTION mail_business_addresses_guard_insert();

CREATE FUNCTION mail_business_addresses_guard_update() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF (NEW.id, NEW.business_id, NEW.address, NEW.domain_id, NEW.attested_by_id, NEW.attested_at, NEW.attestation_version, NEW.created_by_id, NEW.created_at)
     IS DISTINCT FROM (OLD.id, OLD.business_id, OLD.address, OLD.domain_id, OLD.attested_by_id, OLD.attested_at, OLD.attestation_version, OLD.created_by_id, OLD.created_at) THEN
    RAISE EXCEPTION 'address designation is fixed' USING ERRCODE = 'CM005';
  END IF;
  IF OLD.removed_at IS NOT NULL THEN
    RAISE EXCEPTION 'removed designations are final' USING ERRCODE = 'CM006';
  END IF;
  IF NEW.removed_at IS NOT NULL AND EXISTS (
       SELECT 1 FROM "mail_connections" c WHERE c."business_id" = NEW.business_id AND c."business_address_id" = NEW.id AND c."status" <> 'DISCONNECTED') THEN
    RAISE EXCEPTION 'address has a live business mailbox' USING ERRCODE = 'CM010';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER mail_business_addresses_guard_update BEFORE UPDATE ON "mail_business_addresses" FOR EACH ROW EXECUTE FUNCTION mail_business_addresses_guard_update();

-- ---- mail_connection_members -----------------------------------------------------------------
ALTER TABLE "mail_connection_members"
  ADD CONSTRAINT mail_connection_members_access_values CHECK ("access" IN ('READ', 'SEND')),
  ADD CONSTRAINT mail_connection_members_version_positive CHECK ("version" >= 1);

CREATE FUNCTION mail_connection_members_guard() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.business_id, NEW.connection_id, NEW.user_id) IS DISTINCT FROM (OLD.business_id, OLD.connection_id, OLD.user_id) THEN
    RAISE EXCEPTION 'member identity is fixed' USING ERRCODE = 'CM005';
  END IF;
  -- Personal mailboxes have no members (D-C2-3): their only switch is the owner's sharing.
  IF NOT EXISTS (SELECT 1 FROM "mail_connections" c WHERE c."business_id" = NEW.business_id AND c."id" = NEW.connection_id AND c."kind" = 'BUSINESS') THEN
    RAISE EXCEPTION 'only business mailboxes have members' USING ERRCODE = 'CM010';
  END IF;
  NEW.granted_at := now();
  RETURN NEW;
END $$;
CREATE TRIGGER mail_connection_members_guard BEFORE INSERT OR UPDATE ON "mail_connection_members" FOR EACH ROW EXECUTE FUNCTION mail_connection_members_guard();

-- ---- mail_retention_settings -----------------------------------------------------------------
ALTER TABLE "mail_retention_settings"
  -- An explicit, finite period chosen by the business (no product default, D-C2-9). Bounded at 100 years.
  ADD CONSTRAINT mail_retention_settings_days_range CHECK ("ordinary_retention_days" BETWEEN 1 AND 36525),
  ADD CONSTRAINT mail_retention_settings_version_positive CHECK ("version" >= 1);

-- ---- least privilege ---------------------------------------------------------------------------
-- kind, business_address_id and the identities are not updatable by the application (column grants
-- and guard CM005); the holder and principal change only through guard CM008. Designations and domains
-- are removed by marking them, never deleted (they are the record behind business mailboxes).
GRANT UPDATE ("credential_holder_id", "principal_account_id", "provider_tenant_id") ON "mail_connections" TO bos_app;
REVOKE ALL ON "mail_business_domains", "mail_business_addresses", "mail_connection_members", "mail_retention_settings" FROM bos_app;
GRANT SELECT, INSERT ON "mail_business_domains", "mail_business_addresses", "mail_connection_members", "mail_retention_settings" TO bos_app;
GRANT UPDATE ("verified_at", "verified_by_id", "removed_at", "removed_by_id", "version", "updated_at") ON "mail_business_domains" TO bos_app;
GRANT UPDATE ("removed_at", "removed_by_id", "version", "updated_at") ON "mail_business_addresses" TO bos_app;
GRANT UPDATE ("access", "granted_by_id", "granted_at", "version", "updated_at") ON "mail_connection_members" TO bos_app;
GRANT DELETE ON "mail_connection_members" TO bos_app;
GRANT UPDATE ("ordinary_retention_days", "updated_by_id", "version", "updated_at") ON "mail_retention_settings" TO bos_app;

-- ---- row-level security --------------------------------------------------------------------------
ALTER TABLE "mail_business_domains" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_business_domains" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_business_domains" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY created_by_session_user ON "mail_business_domains" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("created_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "mail_business_addresses" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_business_addresses" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_business_addresses" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY created_by_session_user ON "mail_business_addresses" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("created_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "mail_connection_members" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_connection_members" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_connection_members" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY granted_by_session_user_insert ON "mail_connection_members" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("granted_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY granted_by_session_user_update ON "mail_connection_members" AS RESTRICTIVE FOR UPDATE TO bos_app
  USING (true) WITH CHECK ("granted_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

ALTER TABLE "mail_retention_settings" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "mail_retention_settings" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "mail_retention_settings" FOR ALL TO bos_app
  USING      ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid)
  WITH CHECK ("business_id" = nullif(current_setting('app.business_id', true), '')::uuid);
CREATE POLICY set_by_session_user_insert ON "mail_retention_settings" AS RESTRICTIVE FOR INSERT TO bos_app
  WITH CHECK ("updated_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);
CREATE POLICY set_by_session_user_update ON "mail_retention_settings" AS RESTRICTIVE FOR UPDATE TO bos_app
  USING (true) WITH CHECK ("updated_by_id" = nullif(current_setting('app.user_id', true), '')::uuid);

COMMIT;
